/// `nvvm.tcgen05.mma_smem_desc`: Constructs a Shared Memory descriptor for MMA Operands A or B
///
/// The `nvvm.tcgen05_mma_smem_desc` constructs a Shared Memory descriptor
/// for tcgen05.mma. This descriptor is a 64-bit value which describes the
/// properties of multiplicand matrix in shared memory including its location
/// in the shared memory of the current CTA.
///
/// ```text
/// +-----------+------+------------------------------------------------------+
/// | Bit-field | Size | Description                                          |
/// +-----------+------+------------------------------------------------------+
/// | 0-13      | 14   | Matrix start address                                 |
/// | 14-15     | 2    | Reserved                                             |
/// | 16-29     | 14   | Leading dim relative-offset (or) absolute-address    |
/// | 30-31     | 2    | Reserved                                             |
/// | 32-45     | 14   | Stride dimension byte offset                         |
/// | 46-48     | 3    | Fixed constant value of 0b001                        |
/// | 49-51     | 3    | Matrix base offset                                   |
/// | 52        | 1    | Leading dimension stride mode:                       |
/// |           |      |   0: byte offset relative                            |
/// |           |      |   1: byte address absolute                           |
/// | 53-60     | 8    | Fixed constant value of 0xb00000000                  |
/// | 61-63     | 3    | Swizzling mode:                                      |
/// |           |      |   0: No swizzling                                    |
/// |           |      |   1: 128-Byte with 32B atomic swizzling              |
/// |           |      |   2: 128-Byte swizzling                              |
/// |           |      |   4: 64-Byte swizzling                               |
/// |           |      |   6: 32-Byte swizzling                               |
/// |           |      |   (Values 3, 5 and 7 are invalid)                    |
/// +-----------+------+------------------------------------------------------+
/// ```
///
/// Example:
/// ```mlir
///   %desc = nvvm.tcgen05.mma_smem_desc (%startAddr, %leadingDimOffset, %strideDimOffset,
///                                       %baseOffset, %leadingDimMode, %swizzleMode) : (i32, i32, i32, i8, i1, i8) -> i64
/// ```
/// [For more information, see PTX ISA](https://docs.nvidia.com/cuda/parallel-thread-execution/#tcgen05-shared-memory-descriptor)
///
/// Generic form only (directive `operands`).
#[mlir::op("nvvm.tcgen05.mma_smem_desc", results(res))]
pub struct Tcgen05MmaSmemDescOp<'a> {
    #[slot(start_addr_ty, name = "startAddr")]
    pub start_addr: Value<'a>,
    #[slot(leading_dim_offset_ty, name = "leadingDimOffset")]
    pub leading_dim_offset: Value<'a>,
    #[slot(stride_dim_offset_ty, name = "strideDimOffset")]
    pub stride_dim_offset: Value<'a>,
    #[slot(base_offset_ty, name = "baseOffset")]
    pub base_offset: Value<'a>,
    #[slot(leading_dim_mode_ty, name = "leadingDimMode")]
    pub leading_dim_mode: Value<'a>,
    #[slot(swizzle_mode_ty, name = "swizzleMode")]
    pub swizzle_mode: Value<'a>,
    #[dtype(is = i32)]
    pub start_addr_ty: Type<'a>,
    #[dtype(is = i32)]
    pub leading_dim_offset_ty: Type<'a>,
    #[dtype(is = i32)]
    pub stride_dim_offset_ty: Type<'a>,
    #[dtype(is = i8)]
    pub base_offset_ty: Type<'a>,
    #[dtype(is = i1)]
    pub leading_dim_mode_ty: Type<'a>,
    #[dtype(is = i8)]
    pub swizzle_mode_ty: Type<'a>,
    #[dtype(is = i64)]
    pub res: Type<'a>,
}

